FuncDef.Code:
// License: MIT
// https://www.shadertoy.com/view/3fc3zs
float sdChamferBox(in SDFG_VEC p, in vec2 dim2, in float chamfer)
{
    p.xz = abs(p.xz) - dim2;

    p.xz = (p.z>p.x) ? p.zx : p.xz;
    p.z += chamfer;

    const float k = 1.0-sqrt(2.0);
    if( p.z<0.0 && p.z+p.x*k<0.0 )
        return p.x;

    if( p.x<p.z )
        return (p.x+p.z)*sqrt(0.5);    

    return length(p.xz);
}
